    def __init__(self, prefix='', strict=False):
        self.prefix = prefix
        self.strict = strict
        self.errors = {}

    def marshal(self, data, fields_dict):
        """Takes raw data (in the form of a dict, list, object) and a dict of
        fields to output and filters the data based on those fields.

